91		// 区块标识与交易查询仍指向原来的确认结果。
92		for _, tx := range []*Transaction{tx1, tx2} {
93			info, err := n.Tx(tx.ID())
94			if err != nil {
95				t.Fatal(err)
96			}
97			if info.Status != StatusConfirmed || info.BlockHeight != 1 || info.BlockID != p.BlockID {
98				t.Fatalf("tx %s lookup wrong: %+v", tx.ID(), info)
99			}
100		}
101	
102		// 候选历史中的胜出交易列表与确认块一致。
103		rc, err := n.Candidates(1)
104		if err != nil {
105			t.Fatal(err)
106		}
107		var winner *CandidateView
108		for i := range rc.Candidates {
109			if rc.Candidates[i].Result == CandidateWon {
110				winner = &rc.Candidates[i]
111			}
112		}
113		if winner == nil || winner.BlockID != p.BlockID || fmt.Sprint(winner.TxIDs) != fmt.Sprint(want) {
114			t.Fatalf("winner candidate history wrong: %+v", winner)
115		}
