153	// 原确认块仍保留真正确认的交易及其顺序与区块标识，篡改标识不作为交易存在。
154	func TestBlockSnapshotMutationNeverPersisted(t *testing.T) {
155		n, dir, keys, tx1, tx2 := setupTwoTxNode(t)
156		p, _ := n.Propose()
