	}
}

// sameValidators 判断十六进制公钥集合是否恰好包含给定验证者（不多不少）。
func sameValidators(got map[string]bool, want ...testKey) bool {
	if len(got) != len(want) {
		return false
	}
	for _, k := range want {
		if !got[pubHex(k)] {
			return false
		}
	}
	return true
